const test = require('node:test');
const assert = require('node:assert/strict');
const { createNameCache } = require('../names.cjs');
test('invalidates only the selected staff member', () => {
  const c = createNameCache();
  c.set('u17','Lin'); c.set('u28','Mei');
  c.invalidate('u17');
  assert.equal(c.get('u17'), undefined);
  assert.equal(c.get('u28'), 'Mei');
  c.invalidate('missing');
  assert.equal(c.get('u28'), 'Mei');
  c.invalidate('u17');
  assert.equal(c.get('u28'), 'Mei');
  c.set('u28','Mia');
  assert.equal(c.get('u28'), 'Mia');
});
test('cache instances are independent', () => {
  const a = createNameCache(), b = createNameCache();
  a.set('u3','Kai'); b.set('u3','Yun'); a.invalidate('u3');
  assert.equal(b.get('u3'), 'Yun');
});

test('any exact string ID can be invalidated and set again', () => {
  const c = createNameCache();
  for (const id of ['u28','u3','','__proto__']) c.set(id, 'name:' + id);
  for (const id of ['u28','u3','','__proto__']) {
    c.invalidate(id);
    assert.equal(c.get(id), undefined);
    c.set(id, 'updated:' + id);
    assert.equal(c.get(id), 'updated:' + id);
  }
});

